inline unsigned translationCount(){return sizeof(MenuTranslations)/sizeof(MenuTranslations[0]);}
inline std::string localized(const std::string&text,uint32_t language,bool*known=NULL){
 const std::string name=text=="Reset Toggles (Most Of Them)"?"Reset Toggles":text;
 for(unsigned i=0;i<translationCount();++i){const Translation&t=MenuTranslations[i];
  if(name==t.english||name==t.spanish){if(known)*known=true;if(language==Portuguese)return t.portuguese?t.portuguese:t.english;return language==Spanish?t.spanish:t.english;}
 }
 if(known)*known=false;return text;
}
